css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; position: relative; background: repeating-conic-gradient(var(--accent) 0deg 12deg, transparent 12deg 30deg); -webkit-mask: radial-gradient(transparent 30%, #000 31%, #000 92%, transparent 93%); mask: radial-gradient(transparent 30%, #000 31%, #000 92%, transparent 93%); animation: spin calc(var(--loader-speed) * 4) linear infinite; }
.loader::after { content: ''; position: absolute; inset: 32%; border-radius: 50%; background: radial-gradient(circle at 40% 35%, #fff, var(--accent-2)); box-shadow: 0 0 calc(var(--loader-size) * .16) var(--accent-2); }
@keyframes spin { to { transform: rotate(360deg); } }
